const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v2.2/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/document_management/document_revisions/selected_revisions',
  qs: {
    view: 'SOME_STRING_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    locale: 'SOME_STRING_VALUE',
    sort: 'SOME_STRING_VALUE'
  },
  headers: {'content-type': 'application/json'},
  body: {ids: ['string']},
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v2.2/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/document_management/document_revisions/selected_revisions?view=SOME_STRING_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&locale=SOME_STRING_VALUE&sort=SOME_STRING_VALUE"),
    Content = new StringContent("{\"ids\":[\"string\"]}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
